  const validationSchemaStepOne = object<StepOneFormValues>({
    firstName: optional(string()),
    lastName: optional(string())
  });
  const validationSchemaStepTwo = object<StepTwoFormValues>({
    phone: optional(string(mobilePhone())),
    email: optional(string(email()))
  });
  const validationSchemaStepThree = object<StepThreeFormValues>({
    address: optional(string()),
    city: optional(string())
  });
  const validationSchemaStepFour = object<StepFourFormValues>({
    contactChannel: optional(string())
  });
  const StepOne = () => {
    const stepOneForm = useFormContext<StepOneFormValues>();
    return <Grid container rowSpacing={2}>
        <FormTextField required name="firstName" label="Имя" control={stepOneForm.control} />

        <FormTextField required name="lastName" label="Фамилия" control={stepOneForm.control} />
      </Grid>;
  };
  const StepTwo = () => {
    const stepTwoForm = useFormContext<StepTwoFormValues>();
    return <Grid container rowSpacing={2}>
        <FormMobilePhoneField required label="Телефон" name="phone" control={stepTwoForm.control} />

        <FormEmailField label="E-mail" name="email" control={stepTwoForm.control} />
      </Grid>;
  };
  const StepThree = () => {
    const stepThreeForm = useFormContext<StepThreeFormValues>();
    return <Grid container rowSpacing={2}>
        <FormTextField required name="address" label="Адрес" control={stepThreeForm.control} />

        <FormTextField required name="city" label="Город" control={stepThreeForm.control} />
      </Grid>;
  };
  const StepFour = () => {
    const stepFourForm = useFormContext<StepFourFormValues>();
    return <Grid container rowSpacing={2}>
        <FormSelect required control={stepFourForm.control} name="contactChannel" label="Предпочтительный способ связи" getOptionLabel={value => BASIC_USAGE_CONTACT_CHANNEL_OPTIONS.find(option => option.value === value)?.name || ''}>
          {BASIC_USAGE_CONTACT_CHANNEL_OPTIONS.map(({
          value,
          name
        }) => <MenuItem value={value} key={value}>
              {name}
            </MenuItem>)}
        </FormSelect>
      </Grid>;
  };
  const {
    form,
    currentStepId,
    steps,
    isFirstStep,
    isLastStep,
    onClickStep,
    onPrevStep,
    onSubmit
  } = useFormWizard<BasicUsageFormValues>({
    defaultValues: {
      firstName: '',
      lastName: '',
      phone: '',
      email: '',
      address: '',
      city: '',
      contactChannel: ''
    },
    steps: [{
      id: 'stepOne',
      label: 'Личные данные',
      validationSchema: validationSchemaStepOne,
      component: StepOne
    }, {
      id: 'stepTwo',
      label: 'Контактные данные',
      validationSchema: validationSchemaStepTwo,
      component: StepTwo
    }, {
      id: 'stepThree',
      label: 'Адрес',
      validationSchema: validationSchemaStepThree,
      component: StepThree
    }, {
      id: 'stepFour',
      label: 'Связь',
      validationSchema: validationSchemaStepFour,
      component: StepFour
    }],
    onSubmit: mockHandleSubmit
  });
  return <StoryWrapper>
      <FormWizard<BasicUsageFormValues> form={form} currentStepId={currentStepId} isFirstStep={isFirstStep} isLastStep={isLastStep} steps={steps} submitButtonText="Отправить" onClickStep={onClickStep} onPrevStep={onPrevStep} onSubmit={onSubmit} />
    </StoryWrapper>;
