  type ExampleStepOneFormValues = {
    employee: string;
    department: string;
  };
  type ExampleStepTwoFormValues = {
    phone: FormMobilePhoneFieldValue;
    email: FormEmailFieldValue;
  };
  type ExampleFormValues = ExampleStepOneFormValues & ExampleStepTwoFormValues;
  const validationSchemaStepOne = object<ExampleStepOneFormValues>({
    employee: string(),
    department: string()
  });
  const validationSchemaStepTwo = object<ExampleStepTwoFormValues>({
    phone: string(mobilePhone()),
    email: optional(string(email()))
  });
  const prevFormValues = useRef<DeepPartial<ExampleFormValues>>({});
  const handleSubmit = (values: ExampleFormValues) => new Promise<void>(resolve => {
    setTimeout(() => {
      window.alert(JSON.stringify(values, null, 2));
      resolve();
    }, 1000);
  });
  const StepOne = () => {
    const stepOneForm = useFormContext<ExampleFormValues>();
    const handleChangeEmployeeField = (employee: ExampleStepOneFormValues['employee']) => {
      if (Object.is(employee, prevFormValues.current.employee)) {
        return;
      }
      if (employee) {
        stepOneForm.setValue('email', FAKE_EMPLOYEES_EMAIL[employee as keyof typeof FAKE_EMPLOYEES_EMAIL]);
      } else {
        stepOneForm.setValue('email', '');
      }
      prevFormValues.current = {
        employee
      };
    };
    useFormWatchFields<ExampleFormValues>({
      name: 'employee',
      control: stepOneForm.control,
      callback: handleChangeEmployeeField
    });
    return <Grid container rowSpacing={2}>
        <FormSelect required control={stepOneForm.control} name="employee" label="ФИО сотрудника" getOptionLabel={value => FAKE_EMPLOYEES.find(option => option.value === value)?.name || ''}>
          {FAKE_EMPLOYEES.map(({
          value,
          name
        }) => <MenuItem value={value} key={value}>
              {name}
            </MenuItem>)}
        </FormSelect>

        <FormSelect required control={stepOneForm.control} name="department" label="Подразделение" getOptionLabel={value => FAKE_DEPARTMENTS.find(option => option.value === value)?.name || ''}>
          {FAKE_DEPARTMENTS.map(({
          value,
          name
        }) => <MenuItem value={value} key={value}>
              {name}
            </MenuItem>)}
        </FormSelect>
      </Grid>;
  };
  const StepTwo = () => {
    const stepTwoForm = useFormContext<ExampleStepTwoFormValues>();
    return <Grid container rowSpacing={2}>
        <FormMobilePhoneField required label="Телефон" name="phone" control={stepTwoForm.control} />

        <FormEmailField label="E-mail" name="email" control={stepTwoForm.control} />
      </Grid>;
  };
  const {
    form,
    currentStepId,
    steps,
    isFirstStep,
    isLastStep,
    onClickStep,
    onPrevStep,
    onSubmit
  } = useFormWizard<ExampleFormValues>({
    steps: [{
      id: 'stepOne',
      label: 'Личные данные',
      validationSchema: validationSchemaStepOne,
      component: StepOne
    }, {
      id: 'stepTwo',
      label: 'Контактные данные',
      validationSchema: validationSchemaStepTwo,
      component: StepTwo
    }],
    onSubmit: handleSubmit
  });
  return <FormWizard<ExampleFormValues> form={form} currentStepId={currentStepId} isFirstStep={isFirstStep} isLastStep={isLastStep} steps={steps} submitButtonText="Отправить" onClickStep={onClickStep} onPrevStep={onPrevStep} onSubmit={onSubmit} />;
